import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const m=JSON.parse('{"title":"网络攻防","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/网络攻防.md","filePath":"安全方向/网络攻防.md","lastUpdated":1792430298000}'),i={name:"安全方向/网络攻防.md"};function o(h,t,d,n,s,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="网络攻防" tabindex="-1">网络攻防 <a class="header-anchor" href="#网络攻防" aria-label="Permalink to &quot;网络攻防&quot;">​</a></h1><blockquote><p>网安专业的「实战课」。校内对应「网络安全原理」（第 4 学期）、「网络攻防技术」（第 6 学期，核心课），并涉及防火墙原理与技术、入侵检测技术等。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>攻防是理解安全的最佳途径：不知道攻击怎么做，就无法真正防守；</li><li>渗透测试、安全运维、应急响应岗位的核心技能；</li><li>校内实训与学科竞赛的主战场。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/计算机网络.html">计算机网络</a>、<a href="./../专业基础/操作系统.html">操作系统</a></li><li><a href="./../必学工具/Linux.html">Linux 与命令行</a>、<a href="./../必学工具/虚拟机与Kali.html">虚拟机与 Kali</a></li><li><a href="./../必学工具/抓包与流量分析.html">抓包与流量分析</a></li></ul><h2 id="核心内容-攻击视角" tabindex="-1">核心内容（攻击视角） <a class="header-anchor" href="#核心内容-攻击视角" aria-label="Permalink to &quot;核心内容（攻击视角）&quot;">​</a></h2><ul><li>渗透测试流程：信息收集 → 漏洞发现 → 利用 → 提权 → 后渗透 → 报告</li><li>常用技术：端口扫描、漏洞扫描、密码爆破、漏洞利用（Metasploit）、中间人攻击</li><li>Web 攻击入口见 <a href="./Web安全.html">Web 安全</a></li><li>常见防护机制：防火墙、IDS/IPS、WAF、安全基线（见 <a href="./操作系统安全.html">操作系统安全</a>）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《网络攻防技术与实践》（诸葛建伟）</td><td>教材</td><td>中文攻防实战经典，与校内课程契合</td></tr><tr><td>Metasploit 官方文档（<a href="https://docs.metasploit.com/" target="_blank" rel="noreferrer">docs.metasploit.com</a>）</td><td>文档</td><td>框架使用手册</td></tr><tr><td>TryHackMe（<a href="https://tryhackme.com/" target="_blank" rel="noreferrer">tryhackme.com</a>）</td><td>在线平台</td><td>靶机式学习，循序渐进</td></tr><tr><td>HackTheBox（<a href="https://www.hackthebox.com/" target="_blank" rel="noreferrer">hackthebox.com</a>）</td><td>在线平台</td><td>进阶靶场，社区活跃</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>流程大于炫技</strong>：先完整走一遍渗透测试标准流程，输出规范报告（这是岗位要求的核心能力）；</li><li>靶场练习优先：Metasploitable 2、DVWA、VulnHub 等（见 <a href="./../实验与实践/安全实验平台.html">安全实验平台</a>）；</li><li>务必在<strong>授权环境</strong>练习；攻防的本质是责任与边界，违规操作后果严重。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>网络安全原理（第 4 学期，核心课）</li><li>网络攻防技术（第 6 学期，核心课）</li><li>防火墙原理与技术、入侵检测技术（选修方向课）</li></ul>',14)])])}const b=a(i,[["render",o]]);export{m as __pageData,b as default};
